"""Explain stack trace collection, declarations, callbacks and start points."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1941': ('길을 잃었을 때 지나온 길의 표지판을 적으면 어디서 잘못 갔는지 찾기 쉬워요. 스택 추적은 프로그램이 거쳐 온 호출 경로의 주소를 모으는 일과 비슷해요.', '스택 추적의 수집 대상과 배열 용량·반환 개수를 이해합니다.', '주소 네 개를 담을 배열에서 결과 개수가 2이면 0번·1번 칸만 읽는다고 표시하세요.', ['프로그램의 함수는 다른 함수를 부른 뒤 돌아와 일을 계속해요. 실행 스택에는 이런 호출과 복귀에 필요한 정보가 놓일 수 있어요. 스택 추적은 그 정보를 해석해 현재 실행과 관련된 호출 경로 주소를 얻는 기술이에요.', '주소는 실행 코드가 있는 위치를 가리키는 숫자예요. stack_trace_save는 주소를 unsigned long 배열에 모아요. 모든 지역 변수 값이나 프로세스의 메모리 전체를 복사하는 기능이 아니에요. 주소를 함수 이름으로 표시하면 문제 발생 경로를 살펴보는 데 도움이 돼요.', 'store는 결과 배열의 시작 주소이고 size는 배열이 담을 수 있는 주소 항목 개수예요. unsigned long store[4]를 준비했다면 용량은 4예요. 한 항목이 8바이트인 환경에서 배열이 32바이트여도 size에 32를 주면 실제보다 많은 칸이 있다고 잘못 알리는 셈이에요.', '반환값은 실제로 저장한 개수예요. 용량 4에 결과 2라면 store[0]과 store[1]만 수집 결과로 읽어요. 남은 칸까지 새 주소가 채워졌다고 생각하면 안 돼요. 용량은 최대치이고 결과 개수는 실제 사용량이에요.', 'CONFIG_ARCH_STACKWALK 경로에서 이 공통 함수는 배열·용량·건너뛸 개수를 준비한 뒤 arch_stack_walk에 실제 주소 탐색을 맡겨요. 아키텍처는 CPU 종류별 실행 방식과 규칙을 뜻해요. CPU마다 스택을 해석하는 방법이 달라 역할을 나눈 것이에요.', '주소를 모으는 것과 글로 출력하는 것은 별도 작업이에요. 수집 뒤 반환 개수를 사용해 stack_trace_print를 부를 수 있어요. 종이에 A·B 같은 가상 주소를 써서 배열 채우기를 연습할 수 있지만 그 숫자는 실제 CPU에서 얻은 호출 경로가 아니에요.'], [('스택 추적 배열에는 주로 무엇을 모으나요?', ['프로세스의 모든 지역 변수 값을 복사해요', '실행과 관련된 호출 경로의 주소를 모아요'], '정답은 두 번째예요. 주소 목록으로 어디를 거쳐 실행됐는지 살펴봐요. 모든 변수나 메모리 내용을 저장하는 전체 상태 복사와 달라요.'), ('stack_trace_save의 size는 어떤 단위인가요?', ['unsigned long 주소 항목의 개수예요', '언제나 출력 문자열의 바이트 수예요'], '정답은 첫 번째예요. 네 칸 배열이면 용량 4를 알려요. 문자열을 담는 출력 버퍼의 바이트 크기와 수집 배열의 칸 수는 서로 다른 인수예요.')]), 'os1942': ('안내판에 창구 이름과 준비물이 적혀 있다고 창구의 실제 업무가 끝난 것은 아니에요. 함수 선언은 사용할 약속이고 구현은 그 일을 하는 코드예요.', '전방 선언·함수 선언·조건부 컴파일의 차이를 이해합니다.', '함수 선언에는 끝의 세미콜론, 구현에는 중괄호 안의 명령이 있다는 점을 찾아 표시하세요.', ['include/linux/stacktrace.h는 스택 추적 함수를 사용할 때 필요한 선언을 모은 헤더예요. 함수 선언은 이름, 받을 인수, 반환할 값의 타입을 알려 줘요. 선언 끝의 세미콜론만으로 수집 동작이 실행되지는 않아요.', 'struct task_struct;와 struct pt_regs;는 구조체 이름을 먼저 알리는 전방 선언이에요. 상세 구성은 다른 곳에 있어도 그 구조체를 가리키는 포인터를 선언할 수 있어요. 하지만 이것만으로 내부 필드나 전체 크기를 알 수는 없어요.', 'CONFIG_STACKTRACE는 커널을 만들 때 스택 추적 기능을 포함할지 정하는 설정이에요. #ifdef 안의 선언은 해당 조건에 따라 컴파일할 코드에 포함돼요. 실행 중 사용자가 누르는 스위치와는 다른, 빌드 시점의 선택이에요.', 'CONFIG_ARCH_STACKWALK는 CPU별 스택 탐색 인터페이스를 어느 방식으로 연결할지와 관련돼요. 헤더와 kernel/stacktrace.c의 조건을 함께 봐야 지금 살펴보는 구현 경로가 어느 것인지 알 수 있어요. 한 함수 원형을 보았다고 모든 설정에 같은 본문이 있는 것은 아니에요.', 'stub는 기능 대신 제한된 결과를 주는 작은 대체 구현이에요. 이 헤더는 일반 수집 함수 전부에 자동으로 stub를 만들지 않아요. reliable 수집 함수에는 별도 조건의 else에서 -ENOSYS를 반환하는 실제 stub가 있어요. ENOSYS는 기능이 구현되어 있지 않다는 오류예요.', '따라서 설정을 끄면 모든 함수가 0을 돌려준다고 외우지 않아요. 선언이 어떤 조건 안에 있는지, 대체 본문이 실제로 있는지, 빌드에서 어떤 구현과 연결되는지 차례로 확인해요. 선언과 정의를 구별하면 코드가 제공하는 기능을 과장하지 않고 읽을 수 있어요.'], [('함수 원형과 구현 본문은 어떻게 다른가요?', ['원형만 쓰면 모든 연산이 이미 실행돼요', '원형은 호출 약속을 알리고 본문은 실제 명령을 담아요'], '정답은 두 번째예요. 이름·인수·반환형 선언과 중괄호 안의 실행 코드는 역할이 달라요. 해당 설정에서 연결할 구현도 확인해야 해요.'), ('CONFIG_STACKTRACE를 끄면 모든 수집 함수에 0을 반환하는 stub가 자동으로 생기나요?', ['아니요. 각 선언의 조건과 실제 대체 구현을 확인해야 해요', '네. 모든 함수가 언제나 0을 반환해요'], '정답은 첫 번째예요. 조건부 컴파일 자체가 함수 본문을 만들어 주지는 않아요. 이 헤더의 reliable 대체 함수도 0이 아니라 -ENOSYS를 반환해요.')]), 'os1943': ('탐색 담당자가 주소를 하나씩 찾으면 기록 담당자에게 건네줘요. 기록 담당자는 저장 칸과 남은 양을 보고 계속할지 알려 줘요.', 'callback 함수와 cookie 상태, 계속·중단 신호를 이해합니다.', '용량 두 칸·건너뛸 개수 한 개에서 A는 건너뛰고 B·C를 저장하세요. C 저장 직후에는 그만 찾으라는 false를 표시하세요.', ['arch_stack_walk는 CPU별 규칙으로 스택의 주소를 찾는 담당이에요. 주소를 찾을 때마다 consume_entry(cookie, addr)를 호출해 기록 담당자에게 건네요. 이처럼 다른 코드가 나중에 호출하도록 전달하는 함수를 callback, 즉 콜백이라고 해요.', '함수 포인터는 어느 기록 함수를 부를지 가리키는 값이에요. 탐색하는 방법과 주소를 저장하는 정책을 나누면 같은 탐색 인터페이스에 다른 기록 정책을 연결할 수 있어요.', 'cookie는 호출한 쪽이 준비한 상태의 주소예요. 여기서는 store라는 결과 배열, size라는 용량, skip이라는 건너뛸 개수, len이라는 저장 개수를 가진 구조체를 가리켜요. 웹 쿠키나 모든 CPU의 스택 복사본을 뜻하지 않아요.', 'void *는 구체적인 자료형을 드러내지 않은 포인터 표현이에요. 공통 콜백은 이를 stacktrace_cookie 포인터로 받아 원래 상태를 읽고 고쳐요. 탐색이 이 상태를 쓰는 동안 그 구조체와 결과 배열이 계속 유효해야 해요.', '이 콜백은 처음에 공간이 가득 찼으면 false를 반환해 중단을 알려요. 건너뛸 개수가 남으면 하나 줄이고 true로 계속하라고 해요. 그렇지 않으면 주소를 저장하고 개수를 늘린 뒤 공간이 남았는지 반환해요. 따라서 false라고 이번 주소가 무조건 저장되지 않은 것은 아니에요. 마지막 칸을 방금 채워도 false예요.', '용량 2·skip 1에서 주소 A·B·C·D가 순서대로 온다고 해요. A는 건너뛰고 true, B는 첫 칸에 저장하고 true, C는 둘째 칸에 저장하고 false예요. 탐색 쪽은 이 중단 신호를 따라 D를 더 수집하지 않아요. 이 예는 합성 주소로 수집 정책을 따라가는 연습이에요.'], [('cookie는 탐색 함수와 콜백 사이에 무엇을 전달하나요?', ['언제나 모든 CPU 스택의 전역 복사본이에요', '호출한 쪽이 준비한 수집 상태의 주소예요'], '정답은 두 번째예요. 콜백은 그 주소로 배열 용량과 저장 개수 등을 읽고 바꿔요. 실제 상태의 수명도 호출 동안 유지돼야 해요.'), ('수집 콜백의 false는 무엇을 알리나요?', ['추가 수집을 중단하라는 신호예요', '반드시 한 항목을 더 저장하라는 신호예요'], '정답은 첫 번째예요. 이미 가득 찼거나 이번 주소로 마지막 칸을 채우면 false가 될 수 있어요. 저장 여부와 다음 탐색을 계속할지는 구별해야 해요.')]), 'os1944': ('길을 되짚을 때 지금 서 있는 곳에서 시작할 수도 있고, 예전에 적어 둔 위치에서 시작할 수도 있어요. 스택 추적에도 출발점을 고르는 인수가 있어요.', 'task와 저장된 레지스터가 정하는 스택 탐색 출발점을 이해합니다.', '일반 save는 current·NULL, save_regs는 current·regs를 전달한다고 두 줄로 적으세요.', ['task는 커널이 관리하는 실행 주체를 뜻하고 current는 지금 실행 중인 태스크를 가리켜요. regs는 CPU 레지스터 값을 저장한 pt_regs 구조체의 주소예요. 레지스터는 CPU가 계산과 실행 상태를 담는 빠른 저장 자리예요.', '스택 포인터는 현재 스택 위치를 나타내는 값이에요. 레지스터 상태를 저장해 두면 그 안의 스택 위치를 출발점으로 삼아 호출 경로를 살펴볼 수 있어요. regs를 넘긴다는 것은 보통 배열의 다음 칸부터 읽으라는 뜻이 아니에요.', '헤더의 표는 task와 NULL regs를 주면 그 태스크의 스택을 추적한다고 설명해요. current와 regs를 주면 저장된 레지스터의 스택 포인터를 기준으로 시작한다고 설명해요. 두 입력 조합은 서로 다른 출발 정보를 제공해요.', '공통 stack_trace_save는 arch_stack_walk에 current와 NULL을 전달해요. stack_trace_save_regs는 current와 전달받은 regs를 넘겨요. 이 wrapper들은 출발 정보를 전달하며 레지스터 저장 구조 전체를 직접 해석하지 않아요.', 'pt_regs의 실제 필드 구성과 스택을 따라가는 규칙은 CPU별 구현을 봐야 해요. 헤더 표의 regs->stackpointer 표현을 모든 CPU에 그 이름의 동일한 C 필드가 있다는 뜻으로 읽으면 안 돼요. 표는 출발점의 의미를 설명해요.', '두 함수가 넘기는 인수를 종이에 비교하면 공통 코드의 역할을 배울 수 있어요. 실제 인터럽트 진입 때 어떤 레지스터가 저장됐는지와 그 기종의 호출 경로 복원까지 확인하려면 해당 아키텍처 코드를 더 읽어야 해요. 포인터 전달 확인만으로 모든 CPU의 실행을 시험한 것은 아니에요.'], [('current와 regs를 함께 넘기는 경로는 무엇을 출발점으로 삼나요?', ['언제나 다른 태스크의 배열 끝이에요', 'regs에 저장된 스택 포인터에 따른 위치예요'], '정답은 두 번째예요. 헤더 표가 이 인수 조합의 의미를 설명해요. 일반 배열의 인덱스를 옮기는 일과 CPU 실행 상태를 출발점으로 쓰는 일을 구별하세요.'), ('공통 wrapper만 보면 모든 CPU의 pt_regs 구성을 알 수 있나요?', ['아니요. CPU별 구조와 탐색 구현을 확인해야 해요', '네. 모든 CPU의 구조가 똑같아요'], '정답은 첫 번째예요. 공통 함수는 약속된 인터페이스로 포인터를 넘겨요. 그 포인터가 가리키는 세부 레지스터 배치와 해석은 아키텍처별 책임이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_481.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
